def _font(path: str | None, fallbacks: list[Path]) -> Path:
    candidates = [Path(path).expanduser()] if path else []
    candidates.extend(fallbacks)
    for candidate in candidates:
        if candidate.is_file():
            return candidate.resolve()
    raise FileNotFoundError(f"fixture font not found: {[str(item) for item in candidates]}")

def _renderer(path: str | None) -> Path:
    if path:
        candidate = Path(path).resolve()
        if candidate.is_file():
            return candidate
    command = shutil.which("pdftoppm")
    if command:
        return Path(command).resolve()
    raise FileNotFoundError("pdftoppm is required to rasterize the scanned fixture")

def _render_pages(native: Path, renderer: Path, directory: Path) -> list[Path]:
    prefix = directory / "page"
    command = [str(renderer), "-r", "250", "-png", str(native), str(prefix)]
    completed = subprocess.run(command, text=True, encoding="utf-8", errors="replace", capture_output=True)
    if completed.returncode:
        raise RuntimeError(f"pdftoppm failed ({completed.returncode}): {completed.stderr.strip()}")
    pages = sorted(directory.glob("page-*.png"))
    if len(pages) != len(PAGES):
        raise RuntimeError(f"expected {len(PAGES)} rendered pages, found {len(pages)}")
    return pages

def _host_path(value: str, base: Path) -> Path:
    text = value.strip()
    if os.name == "nt":
        match = re.fullmatch(r"/mnt/([A-Za-z])(?:/(.*))?", text.replace("\\", "/"))
        if match:
            suffix = match.group(2) or ""
            return Path(f"{match.group(1).upper()}:/{suffix}").resolve()
    path = Path(text)
    return path.resolve() if path.is_absolute() else (base / path).resolve()

def _git(repo: Path, *arguments: str) -> str:
    completed = subprocess.run(
        ["git", "-C", str(repo), *arguments],
        text=True,
        encoding="utf-8",
        errors="replace",
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
    )
    if completed.returncode:
        raise RuntimeError(
            f"git -C {repo} {' '.join(arguments)} failed with {completed.returncode}: "
            f"{(completed.stderr or completed.stdout).strip()}"
        )
    return completed.stdout.strip()

def _run_ckb(ckb: Path, *arguments: str, environment: dict[str, str] | None = None) -> dict[str, Any]:
    completed = subprocess.run(
        [sys.executable, "-X", "utf8", str(ckb), *arguments],
        text=True,
        encoding="utf-8",
        errors="replace",
        stdin=subprocess.DEVNULL,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        env=environment,
    )
    if completed.returncode:
        raise RuntimeError(
            f"ckb {' '.join(arguments)} failed with {completed.returncode}: "
            f"{(completed.stderr or completed.stdout).strip()}"
        )
    try:
        value = json.loads(completed.stdout)
    except json.JSONDecodeError as exc:
        raise RuntimeError(f"ckb {' '.join(arguments)} returned invalid JSON: {completed.stdout[:500]}") from exc
    if not isinstance(value, dict):
        raise RuntimeError(f"ckb {' '.join(arguments)} did not return one JSON object")
    return value

def _assert_equal(actual: object, expected: object, label: str) -> None:
    if actual != expected:
        raise RuntimeError(f"{label}: expected={expected!r}; actual={actual!r}")

def _assert(condition: bool, label: str) -> None:
    if not condition:
        raise RuntimeError(label)

def _file_evidence(path: Path) -> dict[str, Any]:
    data = path.read_bytes()
    return {
        "path": str(path.resolve()),
        "bytes": len(data),
        "sha256": hashlib.sha256(data).hexdigest(),
    }

def _environment_value(name: str, value: str):
    previous = os.environ.get(name)
    os.environ[name] = value
    try:
        yield
    finally:
        if previous is None:
            os.environ.pop(name, None)
        else:
            os.environ[name] = previous

